# The grandfathered migration deadline (D00 T01 §21 item 3): past this
# date, unmigrated batches read OVERDUE and fail `--check`.
MIGRATION_DEADLINE = "2026-12-31"


def migration_overdue_today(today: str) -> bool:
    """Whether the grandfathered migration is past its deadline."""
    return today > MIGRATION_DEADLINE


# Frozen exemption inventories (D00 T01 §55 item 17). The §21
# provenance set is the run-less findings files. The §55 ratchet
# set is the short-candidate findings-self-path lines counted
# 2026-09-22. Drift fails on any date. Overdue fails after
# MIGRATION_DEADLINE while either set is non-empty.
RATCHET_EXEMPT_LINES = 47
RATCHET_EXEMPT_FILES = 17
PROVENANCE_EXEMPT_FILES = 57
_PROVENANCE_LINE = re.compile(
    r"^Provenance:\s*candidate\s+(\S+);\s*command\s+.+;\s*exit\s+\d+;\s*tool\s+.+;\s*"
    r"digest\s+[0-9a-fA-F]+;\s*path\s+(\S+);\s*run\s+(\S+)\s*$",
    re.M,
)


def exemption_problems(root: Path, today: str) -> list[tuple[str, str]]:
    """Drift and overdue problems for the frozen exemption inventories.

    Each item is `(code, message)`. An empty list means the
    inventories still match and the deadline has not passed, or it
    has passed and both sets are empty.
    """
    reviews = root / "docs" / "reviews"
    runless: set[str] = set()
    ratchet_lines = 0
    ratchet_files: set[str] = set()
    if reviews.is_dir():
        for path in reviews.rglob("*.md"):
            rel = path.relative_to(root).as_posix()
            if not re.search(r"/D\d+-T\d+-s\d+\.md$", "/" + rel):
                continue
            text = path.read_text(encoding="utf-8", errors="replace")
            matched = list(_PROVENANCE_LINE.finditer(text))
            if not any(True for _ in matched):
                # A findings file with no shaped provenance line is
                # the §21 run-less set. Lines that fail the shape are
                # not a run.
                if not re.search(r"(?m)^Provenance:\s*.*\brun\s+\S+", text):
                    runless.add(rel)
            for match in matched:
                cand, recorded, run = match.group(1), match.group(2), match.group(3)
                if run[:8] > "20260919":
                    continue
                short = re.fullmatch(r"[0-9a-fA-F]{40}", cand) is None
                if short or recorded == rel:
                    ratchet_lines += 1
                    ratchet_files.add(rel)
    problems: list[tuple[str, str]] = []
    if len(runless) != PROVENANCE_EXEMPT_FILES:
        problems.append(
            (
                "exemption-drift",
                f"provenance exemption is {len(runless)} files, inventory says {PROVENANCE_EXEMPT_FILES}",
            )
        )
    if ratchet_lines != RATCHET_EXEMPT_LINES or len(ratchet_files) != RATCHET_EXEMPT_FILES:
        problems.append(
            (
                "exemption-drift",
                f"ratchet exemption is {ratchet_lines} lines in {len(ratchet_files)} files, "
                f"inventory says {RATCHET_EXEMPT_LINES} lines in {RATCHET_EXEMPT_FILES} files",
            )
        )
    if today > MIGRATION_DEADLINE and (runless or ratchet_lines):
        problems.append(
            (
                "exemption-overdue",
                f"exemption deadline {MIGRATION_DEADLINE} has passed "
                f"({len(runless)} provenance files, {ratchet_lines} ratchet lines remain)",
            )
        )
    return problems

_PANEL_SLOT_REF_RE = re.compile(r"--slot\s+([a-z0-9][a-z0-9-]*)")
_PANEL_PIN_RE = re.compile(r"gpt-6-(?:sol|astra)|gpt-5\.6-(?:sol|terra)|claude-opus-5-5|claude-(?:opus|sonnet)-5|grok-(?:latest|\d)|--effort|--reasoning-effort|model_reasoning_effort")
_PANEL_SKILLS = (
    ".claude/skills/review-todo-section/SKILL.md",
)


def panel_wiring_problems(root: Path) -> list[tuple[str, str]]:
    """Panel-slot wiring problems (D00 T04 §15).

    Each item is `(code, message)`. The TOML parses with closed sets;
    skill commands name resolving slots and carry no literal pins;
    every governed slot runs through a skill command (R2-F1:
    resolution alone lets an absent failover command pass).
    Missing files skip (fixture roots predate the wiring); a present
    but invalid TOML, an unresolvable slot, a pinned command, or an
    unrun slot fails.
    """
    problems: list[tuple[str, str]] = []
    toml = root / ".conclave" / "panel.toml"
    skills = [root / rel for rel in _PANEL_SKILLS if (root / rel).is_file()]
    if not toml.is_file():
        if skills:
            problems.append(("panel-slots", "panel slots file is missing but skills name slots"))
        return problems
    try:
        slots = panel_slots.load_slots(str(toml))
    except panel_slots.PanelSlotsError as exc:
        return [("panel-slots", str(exc))]
    seen: set[str] = set()
    for path in skills:
        rel = path.relative_to(root).as_posix()
        text = path.read_text(encoding="utf-8", errors="replace")
        for ref in _PANEL_SLOT_REF_RE.findall(text):
            if ref not in slots:
                problems.append(("panel-slots", f"{rel}: --slot {ref} resolves nowhere"))
            else:
                seen.add(ref)
        in_fence = False
        for lnum, line in enumerate(text.splitlines(), 1):
            if line.strip().startswith("```"):
                in_fence = not in_fence
                continue
            if in_fence and _PANEL_PIN_RE.search(line):
                problems.append(("panel-slots", f"{rel}:{lnum} pins a model or effort inside a command"))
    for name in panel_slots.PANEL_SLOTS:
        if name not in seen:
            problems.append(("panel-slots", f"no skill runs --slot {name}"))
    return problems


# An open major older than this many days past its review's stamp is
# overdue by age (D00 T01 §17 item 11; §19 collects accepted plus
# deferred, and a blown row due date also counts). Recorded default: a
# week is long enough to file or defer, short enough to notice; changing
# it is one constant.
PLAN_REVIEW_OVERDUE_DAYS = 7
# Notify lookahead and minute durations (D00 T01 §55 item 23).
# A 9-digit horizon is grammatical and still overflows
# date arithmetic (year 9999). Ten years is past any real
# notice window. Ten years of minutes is past any real
# section duration. Cover ranges are already capped at
# MAX_STAMP_COVERAGE before they are expanded.
NOTIFY_HORIZON_MAX_DAYS = 3660
DURATION_MAX_MINUTES = 5_256_000


